//! Minimal terminal size detection used by clap's `wrap_help` feature.
//!
//! The terminal size is queried (in this order) from stdout, stderr and stdin.

use std::os::raw::{c_int, c_ulong, c_ushort};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: c_ushort,
    ws_col: c_ushort,
    ws_xpixel: c_ushort,
    ws_ypixel: c_ushort,
}

extern "C" {
    fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    fn isatty(fd: c_int) -> c_int;
}

#[cfg(any(target_os = "linux", target_os = "android"))]
const TIOCGWINSZ: c_ulong = 0x5413;
#[cfg(not(any(target_os = "linux", target_os = "android")))]
const TIOCGWINSZ: c_ulong = 0x40087468;

fn size_of_fd(fd: c_int) -> Option<(Width, Height)> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize::default();
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
            return None;
        }
        let rows = ws.ws_row;
        let cols = ws.ws_col;
        if rows > 0 && cols > 0 {
            Some((Width(cols), Height(rows)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal attached to stdout, stderr or stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(1)
        .or_else(|| size_of_fd(2))
        .or_else(|| size_of_fd(0))
}
EOF
echo ok"}

