{"command":"cat > /workspace/src/color.rs <<'EOF'
//! Minimal terminal coloring support.
//!
//! Colors are enabled according to a global override (set from the `--style`
//! option) or, if no override is present, according to the environment
//! (`CLICOLOR_FORCE`, `NO_COLOR`, `CLICOLOR`) and whether stdout is a terminal.

use std::fmt;
use std::io::IsTerminal;
use std::sync::atomic::{AtomicU8, Ordering};
use std::sync::OnceLock;

static OVERRIDE: AtomicU8 = AtomicU8::new(0);
static ENV_DEFAULT: OnceLock<bool> = OnceLock::new();

pub fn set_override(enabled: bool) {
    OVERRIDE.store(if enabled { 2 } else { 1 }, Ordering::Relaxed);
}

fn env_flag(name: &str) -> Option<bool> {
    std::env::var(name).ok().map(|v| v != "0")
}

fn env_default() -> bool {
    *ENV_DEFAULT.get_or_init(|| {
        if env_flag("CLICOLOR_FORCE") == Some(true) {
            return true;
        }
        if env_flag("NO_COLOR").is_some() {
            return false;
        }
        env_flag("CLICOLOR").unwrap_or(true) && std::io::stdout().is_terminal()
    })
}

pub fn colors_enabled() -> bool {
    match OVERRIDE.load(Ordering::Relaxed) {
        2 => true,
        1 => false,
        _ => env_default(),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
}

impl Color {
    fn code(self) -> &'static str {
        match self {
            Color::Red => "31",
            Color::Green => "32",
            Color::Yellow => "33",
            Color::Blue => "34",
            Color::Magenta => "35",
            Color::Cyan => "36",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Styled {
    text: String,
    bold: bool,
    dimmed: bool,
    fg: Option<Color>,
}

impl Styled {
    fn new(text: String) -> Self {
        Styled {
            text,
            bold: false,
            dimmed: false,
            fg: None,
        }
    }

    fn is_plain(&self) -> bool {
        !self.bold && !self.dimmed && self.fg.is_none()
    }
}

impl fmt::Display for Styled {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.is_plain() || !colors_enabled() {
            return f.write_str(&self.text);
        }
        let mut codes: Vec<&str> = Vec::new();
        if self.bold {
            codes.push("1");
        }
        if self.dimmed {
            codes.push("2");
        }
        if let Some(c) = self.fg {
            codes.push(c.code());
        }
        write!(f, "\x1b[{}m{}\x1b[0m", codes.join(";"), self.text)
    }
}

pub trait Colorize: Sized {
    fn into_styled(self) -> Styled;

    fn bold(self) -> Styled {
        let mut s = self.into_styled();
        s.bold = true;
        s
    }
    fn dimmed(self) -> Styled {
        let mut s = self.into_styled();
        s.dimmed = true;
        s
    }
    fn color(self, c: Color) -> Styled {
        let mut s = self.into_styled();
        s.fg = Some(c);
        s
    }
    fn red(self) -> Styled {
        self.color(Color::Red)
    }
    fn green(self) -> Styled {
        self.color(Color::Green)
    }
    fn yellow(self) -> Styled {
        self.color(Color::Yellow)
    }
    fn blue(self) -> Styled {
        self.color(Color::Blue)
    }
    fn magenta(self) -> Styled {
        self.color(Color::Magenta)
    }
    fn cyan(self) -> Styled {
        self.color(Color::Cyan)
    }
}

impl Colorize for Styled {
    fn into_styled(self) -> Styled {
        self
    }
}

impl Colorize for String {
    fn into_styled(self) -> Styled {
        Styled::new(self)
    }
}

impl Colorize for &String {
    fn into_styled(self) -> Styled {
        Styled::new(self.clone())
    }
}

impl Colorize for &str {
    fn into_styled(self) -> Styled {
        Styled::new(self.to_string())
    }
}
EOF
echo ok"}

