        self.mantissa == 0
    }

    fn signed_mantissa_at_scale(&self, scale: u32) -> Option<i128> {
        let factor = pow10(scale - self.scale)?;
        let m = self.mantissa.checked_mul(factor)?;
        let m = i128::try_from(m).ok()?;
        Some(if self.negative { -m } else { m })
    }

    fn from_signed(value: i128, scale: u32) -> Decimal {
        let negative = value < 0;
        let mut mantissa = value.unsigned_abs();
        let mut scale = scale;
        // Reduce precision if the mantissa does not fit
        while mantissa > MAX_MANTISSA && scale > 0 {
            let rem = mantissa % 10;
            mantissa /= 10;
            if rem >= 5 {
                mantissa += 1;
            }
            scale -= 1;
        }
        Decimal {
            negative,
            mantissa,
            scale,
        }
    }

    pub fn add(self, other: Decimal) -> Decimal {
        if self.is_zero() {
            return other;
        }
        if other.is_zero() {
            return self;
        }
        let scale = self.scale.max(other.scale);
        match (
            self.signed_mantissa_at_scale(scale),
            other.signed_mantissa_at_scale(scale),
        ) {
            (Some(a), Some(b)) => match a.checked_add(b) {
                Some(sum) => Decimal::from_signed(sum, scale),
                None => Decimal::from_f64(self.to_f64() + other.to_f64()),
            },
            _ => Decimal::from_f64(self.to_f64() + other.to_f64()),
        }
    }

    pub fn neg(self) -> Decimal {
        Decimal {
            negative: !self.negative,
            ..self
        }
    }

    pub fn sub(self, other: Decimal) -> Decimal {
        self.add(other.neg())
    }

    fn to_f64(self) -> f64 {
        let v = self.mantissa as f64 / 10f64.powi(self.scale as i32);
        if self.negative {
            -v
        } else {
            v
        }
    }

    fn from_f64(v: f64) -> Decimal {
        // Fallback only used in overflow situations.
        let negative = v < 0.0;
        let a = v.abs();
        let mantissa = if a >= MAX_MANTISSA as f64 {
            MAX_MANTISSA
        } else {
            a as u128
        };
        Decimal {
            negative,
            mantissa,
            scale: 0,
        }
    }

    /// Computes `trunc(self / divisor)` as an unsigned number, if the result is non-negative.
    /// Returns `None` for negative results (and division by zero).
    pub fn div_to_usize(self, divisor: Decimal) -> Option<usize> {
        if divisor.is_zero() {
            return None;
        }
        // self / divisor = (m_a / 10^s_a) / (m_b / 10^s_b) = (m_a * 10^s_b) / (m_b * 10^s_a)
        let k = self.scale.min(divisor.scale);
        let e_num = divisor.scale - k;
        let e_den = self.scale - k;
        let quotient: u128 = {
            let num = pow10(e_num).and_then(|p| self.mantissa.checked_mul(p));
            let den = pow10(e_den).and_then(|p| divisor.mantissa.checked_mul(p));
            match (num, den) {
                (Some(n), Some(d)) => n / d,
                (None, Some(_)) => u128::MAX,
                (Some(_), None) => 0,
                (None, None) => u128::MAX,
            }
        };
        let negative = (self.negative != divisor.negative) && !self.is_zero();
        if negative && quotient > 0 {
            return None;
        }
        Some(usize::try_from(quotient).unwrap_or(usize::MAX))
    }

    pub fn parse(s: &str) -> Result<Decimal, &'static str> {
        let bytes = s.as_bytes();
        if bytes.is_empty() {
            return Err("Invalid decimal: empty");
        }

        let mut negative = false;
        let mut point = false;
        let mut has_digits = false;
        let mut mantissa: u128 = 0;
        let mut scale: u32 = 0;
        let mut truncated = false; // further fractional digits are ignored
        let mut rounding_done = false;

        for (i, &b) in bytes.iter().enumerate() {
            let first = i == 0;
            match b {
                b'0'..=b'9' => {
                    let d = (b - b'0') as u128;
                    has_digits = true;
                    if !point {
                        mantissa = mantissa * 10 + d;
                        if mantissa > MAX_MANTISSA {
                            return Err("Invalid decimal: overflow from too many digits");
                        }
                    } else if truncated {
                        if !rounding_done {
                            rounding_done = true;
                            if d >= 5 {
                                mantissa += 1;
                                if mantissa > MAX_MANTISSA {
                                    return Err("Invalid decimal: overflow from too many digits");
                                }
                            }
                        }
                    } else {
                        let next = mantissa * 10 + d;
                        if scale >= MAX_SCALE || next > MAX_MANTISSA {
                            truncated = true;
                            rounding_done = true;
                            if d >= 5 {
                                mantissa += 1;
                                if mantissa > MAX_MANTISSA {
                                    return Err("Invalid decimal: overflow from too many digits");
                                }
                            }
                        } else {
                            mantissa = next;
                            scale += 1;
                        }
                    }
                }
                b'.' if !point => {
                    point = true;
                }
                b'-' if first => {
                    negative = true;
                }
                b'+' if first => {}
                b'_' if has_digits => {}
                b'.' => return Err("Invalid decimal: two decimal points"),
                b'_' => return Err("Invalid decimal: must start lead with a number"),
                _ => return Err("Invalid decimal: unknown character"),
            }
        }

        if !has_digits {
            return Err("Invalid decimal: no digits found");
        }

        Ok(Decimal {
            negative,
            mantissa,
            scale,
        })
    }
}

impl PartialEq for Decimal {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}

impl Eq for Decimal {}

impl PartialOrd for Decimal {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Decimal {
    fn cmp(&self, other: &Self) -> Ordering {
        let a_zero = self.is_zero();
        let b_zero = other.is_zero();
        let a_sign = if a_zero { 0 } else if self.negative { -1 } else { 1 };
        let b_sign = if b_zero { 0 } else if other.negative { -1 } else { 1 };
        if a_sign != b_sign {
            return a_sign.cmp(&b_sign);
        }
        if a_sign == 0 {
            return Ordering::Equal;
        }
        // Same sign, compare magnitudes
        let scale = self.scale.max(other.scale);
        let a = pow10(scale - self.scale).and_then(|p| self.mantissa.checked_mul(p));
        let b = pow10(scale - other.scale).and_then(|p| other.mantissa.checked_mul(p));
        let mag = match (a, b) {
            (Some(a), Some(b)) => a.cmp(&b),
            _ => self
                .to_f64()
                .abs()
                .partial_cmp(&other.to_f64().abs())
                .unwrap_or(Ordering::Equal),
        };
        if a_sign < 0 {
            mag.reverse()
        } else {
            mag
        }
    }
}

impl fmt::Display for Decimal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut digits = self.mantissa.to_string();
        let scale = self.scale as usize;
        if scale > 0 {
            if digits.len() <= scale {
                let pad = scale + 1 - digits.len();
                digits = "0".repeat(pad) + &digits;
            }
            let split = digits.len() - scale;
            digits.insert(split, '.');
        }
        if self.negative && !self.is_zero() {
            write!(f, "-{}", digits)
        } else {
            f.write_str(&digits)
        }
    }
}
