pub type ParameterList = Vec<(String, ParameterValue)>;

pub const MAX_PARAMETERS: usize = 100_000;

const STEP_SIZE_REQUIRED: &str = "A step size is required when the range bounds are floating point numbers. The step size can be specified with the '-D/--parameter-step-size <DELTA>' parameter";

/// Compute the values of a parameter scan.
pub fn range_values(
    min: &str,
    max: &str,
    step: Option<&str>,
) -> Result<Vec<ParameterValue>, String> {
    match step {
        None => {
            let (min, max) = match (min.parse::<i32>(), max.parse::<i32>()) {
                (Ok(a), Ok(b)) => (a, b),
                _ => return Err(STEP_SIZE_REQUIRED.to_string()),
            };
            if min > max {
                return Err("Empty parameter range".to_string());
            }
            let count = max.wrapping_sub(min).wrapping_add(1);
            if count > MAX_PARAMETERS as i32 {
                return Err("Parameter range is too large".to_string());
            }
            let mut values = Vec::new();
            let mut v = min;
            loop {
                values.push(ParameterValue::Int(v));
                if v == max {
                    break;
                }
                v = v.wrapping_add(1);
            }
            Ok(values)
        }
        Some(step) => {
            let parse = |s: &str| {
                Decimal::parse(s).map_err(|e| {
                    format!("Error while parsing parameter scan arguments ({})", e)
                })
            };
            let min = parse(min)?;
            let max = parse(max)?;
            let step = parse(step)?;

            if min > max {
                return Err("Empty parameter range".to_string());
            }
            if step.is_zero() {
                return Err("Zero is not a valid parameter step".to_string());
            }

            let range = max.sub(min).add(Decimal::ONE);
            match range.div_to_usize(step) {
                Some(n) if n <= MAX_PARAMETERS => {}
                _ => return Err("Parameter range is too large".to_string()),
            }

            let mut values = Vec::new();
            let mut v = min;
            while v <= max {
                values.push(ParameterValue::Decimal(v));
                v = v.add(step);
            }
            Ok(values)
        }
    }
}

/// Split a comma-separated list of values. Commas and backslashes can be
/// escaped with a backslash.
pub fn split_list(s: &str) -> Vec<String> {
    let mut items = Vec::new();
    let mut current = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' => match chars.peek() {
                Some(&',') | Some(&'\\') => {
                    current.push(chars.next().unwrap());
                }
                _ => current.push('\\'),
            },
            ',' => items.push(std::mem::take(&mut current)),
            c => current.push(c),
        }
    }
    items.push(current);
    items
}

/// Replace all occurrences of `{name}` in the template by the corresponding
/// parameter values (in a single pass).
pub fn substitute(template: &str, parameters: &ParameterList) -> String {
    if parameters.is_empty() {
        return template.to_string();
    }
    let placeholders: Vec<(String, String)> = parameters
        .iter()
        .map(|(name, value)| (format!("{{{}}}", name), value.to_string()))
        .collect();

    let mut result = String::with_capacity(template.len());
    let mut rest = template;
    'outer: while !rest.is_empty() {
        if rest.starts_with('{') {
            for (placeholder, value) in &placeholders {
                if rest.starts_with(placeholder.as_str()) {
                    result.push_str(value);
                    rest = &rest[placeholder.len()..];
                    continue 'outer;
                }
            }
        }
        let c = rest.chars().next().unwrap();
        result.push(c);
        rest = &rest[c.len_utf8()..];
    }
    result
}
