            .map(|(k, v)| (k.clone(), v.to_string()))
            .collect()
    }
}

/// Build the list of benchmark commands from the command line arguments.
pub fn build_commands(
    command_strings: &[String],
    command_names: &[String],
    parameter_scan: Option<(&str, &str, &str)>,
    step_size: Option<&str>,
    parameter_lists: &[(String, String)],
) -> Result<Vec<Command>, String> {
    if let Some((param_name, min, max)) = parameter_scan {
        let values = parameter::range_values(min, max, step_size)?;
        let combinations: Vec<ParameterList> = values
            .into_iter()
            .map(|v| vec![(param_name.to_string(), v)])
            .collect();
        build_parametrized(command_strings, command_names, combinations)
    } else if !parameter_lists.is_empty() {
        // Check for duplicate parameter names
        let mut names: Vec<&str> = parameter_lists.iter().map(|(n, _)| n.as_str()).collect();
        names.sort_unstable();
        let mut duplicates: Vec<&str> = names
            .windows(2)
            .filter(|w| w[0] == w[1])
            .map(|w| w[0])
            .collect();
        duplicates.dedup();
        if !duplicates.is_empty() {
            return Err(format!(
                "Duplicate parameter names: {}",
                duplicates.join(", ")
            ));
        }

        let lists: Vec<(String, Vec<String>)> = parameter_lists
            .iter()
            .map(|(name, values)| (name.clone(), parameter::split_list(values)))
            .collect();

        // Cartesian product, the first parameter varies fastest
        let total: usize = lists.iter().map(|(_, v)| v.len()).product();
        let mut combinations: Vec<ParameterList> = Vec::with_capacity(total);
        let mut indices = vec![0usize; lists.len()];
        if total > 0 {
            loop {
                let combo: ParameterList = lists
                    .iter()
                    .zip(indices.iter())
                    .map(|((name, values), &i)| {
                        (name.clone(), ParameterValue::Text(values[i].clone()))
                    })
                    .collect();
                combinations.push(combo);

                // increment
                let mut pos = 0;
                loop {
                    if pos == lists.len() {
                        break;
                    }
                    indices[pos] += 1;
                    if indices[pos] < lists[pos].1.len() {
                        break;
                    }
                    indices[pos] = 0;
                    pos += 1;
                }
                if pos == lists.len() {
                    break;
                }
            }
        }
        build_parametrized(command_strings, command_names, combinations)
    } else {
        if command_names.len() > command_strings.len() {
            return Err(format!(
                "Too many --command-name options: Expected {} at most",
                command_strings.len()
            ));
        }
        Ok(command_strings
            .iter()
            .enumerate()
            .map(|(i, cmd)| Command::new(command_names.get(i).map(|s| s.as_str()), cmd))
            .collect())
    }
}

fn build_parametrized(
    command_strings: &[String],
    command_names: &[String],
    combinations: Vec<ParameterList>,
) -> Result<Vec<Command>, String> {
    let n_benchmarks = combinations.len() * command_strings.len();
    if command_names.len() > 1 && command_names.len() != n_benchmarks {
        return Err(format!(
            "'--command-name' has been specified {} times. It has to appear exactly once, or exactly {} times (number of benchmarks)",
            command_names.len(),
            n_benchmarks
        ));
    }

    let mut commands = Vec::with_capacity(n_benchmarks);
    let mut index = 0;
    for combination in combinations {
        for cmd in command_strings {
            let name = if command_names.len() == 1 {
                Some(command_names[0].as_str())
            } else {
                command_names.get(index).map(|s| s.as_str())
            };
            commands.push(Command::new_parametrized(name, cmd, combination.clone()));
            index += 1;
        }
    }
    Ok(commands)
}
