            Some("nocolor") => OutputStyleOption::NoColor,
            Some("color") => OutputStyleOption::Color,
            Some("none") => OutputStyleOption::Disabled,
            _ => {
                if command_output_policies
                    .iter()
                    .any(|p| *p == CommandOutputPolicy::Inherit)
                    || !std::io::stdout().is_terminal()
                {
                    OutputStyleOption::Basic
                } else if colors_supported_by_terminal() {
                    OutputStyleOption::Full
                } else {
                    OutputStyleOption::NoColor
                }
            }
        };

        match output_style {
            OutputStyleOption::Basic | OutputStyleOption::NoColor | OutputStyleOption::Disabled => {
                color::set_override(false)
            }
            OutputStyleOption::Full | OutputStyleOption::Color => color::set_override(true),
        }

        let (sort_order_speed_comparison, sort_order_exports) =
            match matches.get_one::<String>("sort").map(|s| s.as_str()) {
                None | Some("auto") => (SortOrder::MeanTime, SortOrder::Command),
                Some("command") => (SortOrder::Command, SortOrder::Command),
