                for part in v.split(',') {
                    let code = part.trim().parse::<i32>().map_err(|e| {
                        format!(
                            "Could not read numeric integer argument to '--ignore-failure': {}",
                            e
                        )
                    })?;
                    codes.push(code);
                }
                CmdFailureAction::IgnoreSpecificFailures(codes)
            }
        };

        let min_benchmarking_time = match matches.get_one::<String>("min-benchmarking-time") {
            None => DEFAULT_MIN_BENCHMARKING_TIME,
            Some(s) => s.parse::<f64>().map_err(|e| {
                format!(
                    "Could not read numeric floating point argument to '--min-benchmarking-time': {}",
                    e
                )
            })?,
        };

        let time_unit = match matches.get_one::<String>("time-unit").map(|s| s.as_str()) {
            Some("microsecond") => Some(Unit::MicroSecond),
            Some("millisecond") => Some(Unit::MilliSecond),
            Some("second") => Some(Unit::Second),
            _ => None,
        };

        let command_input_policy = match matches.get_one::<String>("input").map(|s| s.as_str()) {
            None | Some("null") => CommandInputPolicy::Null,
            Some(path) => {
                if !Path::new(path).exists() {
                    return Err(format!(
                        "The file '{}' specified as '--input' does not exist",
                        path
                    ));
                }
                CommandInputPolicy::File(PathBuf::from(path))
            }
        };

        Ok(Options {
            warmup_count,
            run_bounds,
            min_benchmarking_time,
            setup_command,
            preparation_command,
            conclusion_command,
            cleanup_command,
            command_failure_action,
            output_style,
            sort_order_speed_comparison,
            sort_order_exports,
            executor_kind,
            command_output_policies,
            command_input_policy,
            time_unit,
        })
    }

    pub fn validate_against_command_list(&self, commands: &[Command]) -> Result<(), String> {
        let n = commands.len();
        let check = |count: usize, option: &str| -> Result<(), String> {
            if count > 1 && count != n {
                Err(format!(
                    "The '{}' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).",
                    option, n
                ))
            } else {
                Ok(())
            }
        };
        if let Some(p) = &self.preparation_command {
            check(p.len(), "--prepare")?;
        }
        if let Some(c) = &self.conclusion_command {
            check(c.len(), "--conclude")?;
        }
        check(self.command_output_policies.len(), "--output")?;
        Ok(())
    }

    pub fn output_policy_for(&self, index: usize) -> &CommandOutputPolicy {
        if self.command_output_policies.len() == 1 {
            &self.command_output_policies[0]
        } else {
            &self.command_output_policies[index]
        }
    }

    pub fn preparation_for(&self, index: usize) -> Option<&str> {
        self.preparation_command.as_ref().map(|v| {
            if v.len() == 1 {
                v[0].as_str()
            } else {
                v[index].as_str()
            }
        })
    }

    pub fn conclusion_for(&self, index: usize) -> Option<&str> {
        self.conclusion_command.as_ref().map(|v| {
            if v.len() == 1 {
                v[0].as_str()
            } else {
                v[index].as_str()
            }
        })
    }
}
