//! Basic statistics.

pub fn mean(values: &[f64]) -> f64 {
    let sum = values.iter().fold(0.0, |acc, &x| acc + x);
    sum / values.len() as f64
}

pub fn standard_deviation(values: &[f64], mean: f64) -> f64 {
    let sum = values
        .iter()
        .fold(0.0, |acc, &x| acc + (x - mean) * (x - mean));
    (sum / (values.len() as f64 - 1.0)).sqrt()
}

pub fn median(values: &[f64]) -> f64 {
    let mut v = values.to_vec();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let len = v.len();
    if len % 2 == 0 {
        (v[len / 2 - 1] + v[len / 2]) / 2.0
    } else {
        v[len / 2]
    }
}

pub fn min(values: &[f64]) -> f64 {
    values.iter().copied().fold(f64::INFINITY, f64::min)
}

pub fn max(values: &[f64]) -> f64 {
    values.iter().copied().fold(f64::NEG_INFINITY, f64::max)
}

/// Threshold for the modified Z-score above which a data point is considered an outlier.
/// The factor 1.4826 converts the MAD to an estimator of the standard deviation.
pub const OUTLIER_THRESHOLD: f64 = 1.4826 * 10.0;

/// Modified Z-scores `(x_i - median) / MAD`, where MAD is the median absolute deviation.
pub fn modified_zscores(values: &[f64]) -> Vec<f64> {
    let x_median = median(values);
    let deviations: Vec<f64> = values.iter().map(|x| (x - x_median).abs()).collect();
    let mad = median(&deviations);
    values.iter().map(|&x| (x - x_median) / mad).collect()
}
