//! Executors run (and time) commands: directly, through a shell, or as a mock.

use std::fs::File;
use std::io::Read;
use std::os::unix::process::ExitStatusExt;
use std::process::{Command as ProcessCommand, Stdio};
use std::time::Instant;

use super::timing_result::TimingResult;
use crate::options::{
    CmdFailureAction, CommandInputPolicy, CommandOutputPolicy, OutputStyleOption, Shell,
};
use crate::progress::ProgressBar;
use crate::shell_words;
use crate::stats;
use crate::units::Second;

/// Exit status of a command execution
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ExitInfo {
    pub code: Option<i32>,
    pub signal: Option<i32>,
}

impl ExitInfo {
    pub fn success() -> ExitInfo {
        ExitInfo {
            code: Some(0),
            signal: None,
        }
    }

    pub fn is_success(&self) -> bool {
        self.code == Some(0)
    }

    /// The exit code, where termination by a signal is reported as 128 + signal number.
    pub fn effective_code(&self) -> Option<i32> {
        self.code.or_else(|| self.signal.map(|s| 128 + s))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BenchmarkIteration {
    NonBenchmarkRun,
    Warmup(u64),
    Benchmark(u64),
}

impl BenchmarkIteration {
    fn to_env_var_value(self) -> Option<String> {
        match self {
            BenchmarkIteration::NonBenchmarkRun => None,
            BenchmarkIteration::Warmup(i) => Some(format!("warmup-{}", i)),
            BenchmarkIteration::Benchmark(i) => Some(format!("{}", i)),
        }
    }

    fn describe(self) -> String {
        match self {
            BenchmarkIteration::Warmup(0) => "the first warmup run".to_string(),
            BenchmarkIteration::Warmup(i) => format!("warmup iteration {}", i),
            BenchmarkIteration::Benchmark(0) => "the first benchmark run".to_string(),
            BenchmarkIteration::Benchmark(i) => format!("benchmark iteration {}", i),
            BenchmarkIteration::NonBenchmarkRun => "a non-benchmark run".to_string(),
        }
    }
}

#[repr(C)]
#[derive(Default, Clone, Copy)]
struct Timeval {
    tv_sec: i64,
    tv_usec: i64,
}

#[repr(C)]
#[derive(Default, Clone, Copy)]
struct Rusage {
    ru_utime: Timeval,
    ru_stime: Timeval,
    ru_maxrss: i64,
    ru_ixrss: i64,
    ru_idrss: i64,
    ru_isrss: i64,
    ru_minflt: i64,
    ru_majflt: i64,
    ru_nswap: i64,
    ru_inblock: i64,
    ru_oublock: i64,
    ru_msgsnd: i64,
    ru_msgrcv: i64,
    ru_nsignals: i64,
    ru_nvcsw: i64,
    ru_nivcsw: i64,
}

extern "C" {
    fn getrusage(who: i32, usage: *mut Rusage) -> i32;
}

const RUSAGE_CHILDREN: i32 = -1;

#[derive(Debug, Clone, Copy)]
struct ChildrenUsage {
    user_usec: i64,
    system_usec: i64,
    maxrss_kb: i64,
}

fn children_usage() -> ChildrenUsage {
    let mut usage = Rusage::default();
    unsafe {
        getrusage(RUSAGE_CHILDREN, &mut usage as *mut Rusage);
    }
    ChildrenUsage {
        user_usec: usage.ru_utime.tv_sec * 1_000_000 + usage.ru_utime.tv_usec,
        system_usec: usage.ru_stime.tv_sec * 1_000_000 + usage.ru_stime.tv_usec,
        maxrss_kb: usage.ru_maxrss,
    }
}

/// Spawn the given program, wait for it to finish and measure the time.
fn execute_and_measure(
    program: &str,
    args: &[String],
    iteration: BenchmarkIteration,
    output_policy: &CommandOutputPolicy,
    input_policy: &CommandInputPolicy,
) -> std::io::Result<(TimingResult, ExitInfo)> {
    let mut command = ProcessCommand::new(program);
    command.args(args);

    if let Some(value) = iteration.to_env_var_value() {
        command.env("HYPERFINE_ITERATION", value);
    }

    match input_policy {
        CommandInputPolicy::Null => {
            command.stdin(Stdio::null());
        }
        CommandInputPolicy::File(path) => {
            let file = File::open(path)?;
            command.stdin(Stdio::from(file));
        }
    }

    let mut read_pipe = false;
    match output_policy {
        CommandOutputPolicy::Null => {
            command.stdout(Stdio::null());
            command.stderr(Stdio::null());
        }
        CommandOutputPolicy::Pipe => {
            command.stdout(Stdio::piped());
            command.stderr(Stdio::null());
            read_pipe = true;
        }
        CommandOutputPolicy::File(path) => {
            let file = File::create(path)?;
            command.stdout(Stdio::from(file));
            command.stderr(Stdio::null());
        }
        CommandOutputPolicy::Inherit => {
            command.stdout(Stdio::inherit());
            command.stderr(Stdio::inherit());
        }
    }

    let usage_before = children_usage();
    let start = Instant::now();

    let mut child = command.spawn()?;
    if read_pipe {
        if let Some(mut stdout) = child.stdout.take() {
            let mut buffer = [0u8; 8192];
            loop {
                match stdout.read(&mut buffer) {
                    Ok(0) => break,
                    Ok(_) => continue,
                    Err(ref e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(_) => break,
                }
            }
        }
    }
    let status = child.wait()?;

    let elapsed = start.elapsed();
    let usage_after = children_usage();

    let time_real = elapsed.as_secs() as f64 + f64::from(elapsed.subsec_nanos()) * 1e-9;
    let time_user = (usage_after.user_usec - usage_before.user_usec) as f64 * 1e-6;
    let time_system = (usage_after.system_usec - usage_before.system_usec) as f64 * 1e-6;
    let memory_usage_byte = (usage_after.maxrss_kb.max(0) as u64) * 1024;

    Ok((
        TimingResult {
            time_real,
            time_user,
            time_system,
            memory_usage_byte,
        },
        ExitInfo {
            code: status.code(),
            signal: status.signal(),
        },
    ))
}

/// Check the exit status of a command according to the failure policy.
fn check_status(
    status: &ExitInfo,
    iteration: BenchmarkIteration,
    failure_action: Option<&CmdFailureAction>,
) -> Result<(), String> {
    let action = match failure_action {
        None => return Ok(()),
        Some(a) => a,
    };
    if status.is_success() {
        return Ok(());
    }
    let ignored = match action {
        CmdFailureAction::RaiseError => false,
        CmdFailureAction::IgnoreAllFailures => true,
        CmdFailureAction::IgnoreSpecificFailures(codes) => status
            .effective_code()
            .map(|c| codes.contains(&c))
            .unwrap_or(false),
    };
    if ignored {
        return Ok(());
    }
    let cause = match status.code {
        Some(code) => format!("Command terminated with non-zero exit code {}", code),
        None => "The process has been terminated by a signal".to_string(),
    };
    Err(format!(
