//! A simple progress bar, drawn to stderr (only if stderr is an interactive terminal).

use std::io::{IsTerminal, Write};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use crate::options::OutputStyleOption;

const TICK_CHARS: [char; 10] = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
const TICK_INTERVAL: Duration = Duration::from_millis(80);

struct State {
    len: u64,
    pos: u64,
    message: String,
    tick: usize,
    start: Instant,
    drawn: bool,
}

pub struct ProgressBar {
    state: Option<Arc<Mutex<State>>>,
    stop: Arc<AtomicBool>,
    ticker: Mutex<Option<JoinHandle<()>>>,
}

fn terminal_width() -> usize {
    terminal_size::terminal_size()
        .map(|(w, _)| w.0 as usize)
        .unwrap_or(80)
}

/// Width of a string on the terminal (ANSI escape sequences are ignored).
fn visible_width(s: &str) -> usize {
    crate::cli::strip_ansi(s).chars().count()
}

fn format_eta(d: Duration) -> String {
    let secs = d.as_secs();
    format!("{:02}:{:02}:{:02}", secs / 3600, (secs / 60) % 60, secs % 60)
}

fn draw(state: &mut State) {
    let width = terminal_width();
    let spinner = TICK_CHARS[state.tick % TICK_CHARS.len()];

    let mut message = state.message.clone();
    let msg_width = visible_width(&message);
    if msg_width < 30 {
        message.push_str(&" ".repeat(30 - msg_width));
    }

    let eta = if state.pos == 0 || state.pos >= state.len {
        Duration::from_secs(0)
    } else {
        let elapsed = state.start.elapsed().as_secs_f64();
        let per_step = elapsed / state.pos as f64;
        Duration::from_secs_f64(per_step * (state.len - state.pos) as f64)
    };
    let eta = format_eta(eta);

    let fixed = 1 + 1 + 1 + visible_width(&message) + 1 + 5 + eta.chars().count() + 1;
    let bar_width = width.saturating_sub(fixed).max(1);
    let filled = if state.len == 0 {
        0
    } else {
        ((state.pos.min(state.len) as f64 / state.len as f64) * bar_width as f64) as usize
    };
    let bar = format!(
        "{}{}",
        "█".repeat(filled),
        "░".repeat(bar_width.saturating_sub(filled))
    );

    let line = format!(" {} {} {} ETA {} ", spinner, message, bar, eta);

    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    if state.drawn {
        let _ = write!(lock, "\r\x1b[2K{}", line);
    } else {
        let _ = write!(lock, "{}", line);
    }
    let _ = lock.flush();
    state.drawn = true;
}

impl ProgressBar {
    pub fn new(len: u64, message: &str, style: OutputStyleOption) -> ProgressBar {
        let enabled = matches!(style, OutputStyleOption::Full | OutputStyleOption::NoColor)
            && std::io::stderr().is_terminal();
        let stop = Arc::new(AtomicBool::new(false));
        if !enabled {
            return ProgressBar {
                state: None,
                stop,
                ticker: Mutex::new(None),
            };
        }

        let state = Arc::new(Mutex::new(State {
            len,
            pos: 0,
            message: message.to_string(),
            tick: 0,
            start: Instant::now(),
            drawn: false,
        }));

        {
            let mut s = state.lock().unwrap();
            draw(&mut s);
        }

        let thread_state = Arc::clone(&state);
        let thread_stop = Arc::clone(&stop);
        let handle = std::thread::spawn(move || loop {
            let mut waited = Duration::from_millis(0);
            while waited < TICK_INTERVAL {
                if thread_stop.load(Ordering::SeqCst) {
                    return;
                }
                std::thread::sleep(Duration::from_millis(5));
                waited += Duration::from_millis(5);
            }
            if thread_stop.load(Ordering::SeqCst) {
                return;
            }
            let mut s = thread_state.lock().unwrap();
            s.tick += 1;
            draw(&mut s);
        });

        ProgressBar {
            state: Some(state),
            stop,
            ticker: Mutex::new(Some(handle)),
        }
    }

    pub fn inc(&self, delta: u64) {
        if let Some(state) = &self.state {
            let mut s = state.lock().unwrap();
            s.pos = s.pos.saturating_add(delta);
            draw(&mut s);
        }
    }

    pub fn set_length(&self, len: u64) {
        if let Some(state) = &self.state {
            let mut s = state.lock().unwrap();
            s.len = len;
        }
    }

    pub fn set_message(&self, message: String) {
        if let Some(state) = &self.state {
            let mut s = state.lock().unwrap();
            s.message = message;
        }
    }

    pub fn finish_and_clear(&self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Some(handle) = self.ticker.lock().unwrap().take() {
            let _ = handle.join();
        }
        if let Some(state) = &self.state {
            let mut s = state.lock().unwrap();
            if s.drawn {
                let stderr = std::io::stderr();
                let mut lock = stderr.lock();
                let _ = write!(lock, "\r\x1b[2K");
                let _ = lock.flush();
                s.drawn = false;
            }
        }
    }
}

impl Drop for ProgressBar {
    fn drop(&mut self) {
        self.finish_and_clear();
    }
}
