//! Warnings that are shown after a benchmark.

use std::fmt;

use crate::units::{format_duration, Second};

pub struct OutlierWarningOptions {
    pub warmup_in_use: bool,
    pub prepare_in_use: bool,
}

pub enum Warnings {
    FastExecutionTime,
    NonZeroExitCode,
    SlowInitialRun(Second, OutlierWarningOptions),
    OutliersDetected(OutlierWarningOptions),
}

impl fmt::Display for Warnings {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Warnings::FastExecutionTime => write!(
                f,
                "Command took less than 5 ms to complete. Note that the results might be \
                 inaccurate because hyperfine can not calibrate the shell startup time much \
                 more precise than this limit. You can try to use the `-N`/`--shell=none` \
                 option to disable the shell completely."
            ),
            Warnings::NonZeroExitCode => write!(f, "Ignoring non-zero exit code."),
            Warnings::SlowInitialRun(time_first_run, options) => {
                write!(
                    f,
                    "The first benchmarking run for this command was significantly slower than the \
                     rest ({}). This could be caused by (filesystem) caches that were not filled until \
                     after the first run. {}",
                    format_duration(*time_first_run, None),
                    match (options.warmup_in_use, options.prepare_in_use) {
                        (true, true) => "You are already using both the '--warmup' option as well \
                                         as the '--prepare' option. Consider re-running the benchmark \
                                         on a quiet system. Maybe it was a random outlier. Alternatively, \
                                         consider increasing the warmup count.",
                        (true, false) => "You are already using the '--warmup' option which helps \
                                          to fill these caches before the actual benchmark. You can \
                                          either try to increase the warmup count further or re-run \
                                          this benchmark on a quiet system in case it was a random \
                                          outlier. Alternatively, consider using the '--prepare' option \
                                          to clear the caches before each timing run.",
                        (false, true) => "You are already using the '--prepare' option which can be \
                                          used to clear caches. If you did not use a cache-clearing \
                                          command with '--prepare', you can either try that or consider \
                                          using the '--warmup' option to fill those caches before the \
                                          actual benchmark.",
                        (false, false) => "You should consider using the '--warmup' option to fill \
                                           those caches before the actual benchmark. Alternatively, use \
                                           the '--prepare' option to clear the caches before each timing \
                                           run.",
                    }
                )
            }
            Warnings::OutliersDetected(options) => {
                write!(
                    f,
                    "Statistical outliers were detected. Consider re-running this benchmark on a quiet \
                     system without any interferences from other programs."
                )?;
                if !(options.warmup_in_use && options.prepare_in_use) {
                    write!(
                        f,
                        " It might help to use the '--warmup' or '--prepare' options."
                    )?;
                }
                Ok(())
            }
        }
    }
}
