//! Running a single benchmark.

pub mod benchmark_result;
pub mod executor;
pub mod process;
pub mod relative_speed;
pub mod scheduler;
pub mod timing_result;

use std::cmp;

use crate::color::Colorize;
use crate::command::Command;
use crate::options::{CmdFailureAction, CommandOutputPolicy, OutputStyleOption, Options};
use crate::progress::ProgressBar;
use crate::stats;
use crate::units::{format_duration, format_duration_unit, Second};
use crate::warnings::{OutlierWarningOptions, Warnings};

use benchmark_result::BenchmarkResult;
use executor::Executor;
use process::BenchmarkIteration;
use timing_result::TimingResult;

/// Threshold for warning about fast execution time
pub const MIN_EXECUTION_TIME: Second = 5e-3;

pub struct Benchmark<'a> {
    number: usize,
    command: &'a Command,
    options: &'a Options,
    executor: &'a dyn Executor,
}

impl<'a> Benchmark<'a> {
    pub fn new(
        number: usize,
        command: &'a Command,
        options: &'a Options,
        executor: &'a dyn Executor,
    ) -> Self {
        Benchmark {
            number,
            command,
            options,
            executor,
        }
    }

    fn output_policy(&self) -> &CommandOutputPolicy {
        self.options.output_policy_for(self.number)
    }

    /// Run an auxiliary command (setup, prepare, conclude, cleanup).
    fn run_intermediate_command(
        &self,
        command: &str,
        error_output: &'static str,
    ) -> Result<TimingResult, String> {
        let command_line = self.command.substitute_into(command);
        self.executor
            .run_command_and_measure(
                &command_line,
                BenchmarkIteration::NonBenchmarkRun,
                Some(&CmdFailureAction::RaiseError),
                self.output_policy(),
            )
            .map(|(result, _)| result)
            .map_err(|_| error_output.to_string())
    }

    fn run_setup_command(&self) -> Result<TimingResult, String> {
        match &self.options.setup_command {
            Some(cmd) => self.run_intermediate_command(
                cmd,
                "The setup command terminated with a non-zero exit code. \
                 Append ' || true' to the command if you are sure that this can be ignored.",
            ),
            None => Ok(TimingResult::default()),
        }
    }

    fn run_cleanup_command(&self) -> Result<TimingResult, String> {
        match &self.options.cleanup_command {
            Some(cmd) => self.run_intermediate_command(
                cmd,
                "The cleanup command terminated with a non-zero exit code. \
                 Append ' || true' to the command if you are sure that this can be ignored.",
            ),
            None => Ok(TimingResult::default()),
        }
    }

    fn run_preparation_command(&self) -> Result<TimingResult, String> {
        match self.options.preparation_for(self.number) {
            Some(cmd) => self.run_intermediate_command(
                cmd,
                "The preparation command terminated with a non-zero exit code. \
                 Append ' || true' to the command if you are sure that this can be ignored.",
            ),
            None => Ok(TimingResult::default()),
        }
    }

    fn run_conclusion_command(&self) -> Result<TimingResult, String> {
        match self.options.conclusion_for(self.number) {
            Some(cmd) => self.run_intermediate_command(
                cmd,
                "The conclusion command terminated with a non-zero exit code. \
                 Append ' || true' to the command if you are sure that this can be ignored.",
            ),
            None => Ok(TimingResult::default()),
        }
    }

    pub fn run(&self) -> Result<BenchmarkResult, String> {
        let style = self.options.output_style;

        if style != OutputStyleOption::Disabled {
            println!(
                "{}{}: {}",
                "Benchmark ".bold(),
                (self.number + 1).to_string().bold(),
                self.command.get_name_with_unused_parameters(),
            );
        }

        let mut times_real: Vec<Second> = vec![];
        let mut times_user: Vec<Second> = vec![];
        let mut times_system: Vec<Second> = vec![];
        let mut memory_usage_byte: Vec<u64> = vec![];
        let mut exit_codes: Vec<Option<i32>> = vec![];
        let mut all_succeeded = true;

        let command_line = self.command.get_command_line();
        let failure_action = &self.options.command_failure_action;

        self.run_setup_command()?;

        // Warmup phase
        if self.options.warmup_count > 0 {
            let bar = ProgressBar::new(self.options.warmup_count, "Performing warmup runs", style);
