        self.indent(level);
        escape_string(key, &mut self.out);
        self.out.push_str(": ");
    }

    fn array<T, F: Fn(&T) -> String>(&mut self, level: usize, items: &[T], f: F) {
        if items.is_empty() {
            self.out.push_str("[]");
            return;
        }
        self.out.push_str("[\n");
        for (i, item) in items.iter().enumerate() {
            self.indent(level + 1);
            self.out.push_str(&f(item));
            if i + 1 < items.len() {
