use crate::benchmark::benchmark_result::BenchmarkResult;
use crate::options::SortOrder;
use crate::units::Unit;

#[derive(Default)]
pub struct CsvExporter {}

fn escape_field(field: &str) -> String {
    let needs_quotes = field
        .chars()
        .any(|c| c == ',' || c == '"' || c == '\n' || c == '\r');
    if needs_quotes {
        format!("\"{}\"", field.replace('"', "\"\""))
    } else {
        field.to_string()
    }
}

struct CsvWriter {
    out: String,
    expected_fields: Option<usize>,
}

impl CsvWriter {
    fn write_record(&mut self, fields: &[String]) -> Result<(), String> {
        if let Some(expected) = self.expected_fields {
            if expected != fields.len() {
                return Err(format!(
                    "CSV error: found record with {} fields, but the previous record has {} fields",
                    fields.len(),
                    expected
                ));
            }
        } else {
            self.expected_fields = Some(fields.len());
        }
        let line: Vec<String> = fields.iter().map(|f| escape_field(f)).collect();
        self.out.push_str(&line.join(","));
        self.out.push('\n');
        Ok(())
    }
}

impl Exporter for CsvExporter {
    fn serialize(
        &self,
        results: &[BenchmarkResult],
        _unit: Option<Unit>,
