//! hyperfine: a command-line benchmarking tool.

mod benchmark;
mod cli;
mod color;
mod command;
mod decimal;
mod export;
mod options;
mod parameter;
mod progress;
mod shell_words;
mod stats;
mod units;
mod warnings;

use benchmark::scheduler::Scheduler;
use color::Colorize;
use command::{build_commands, Command};
use export::ExportManager;
use options::Options;

fn run() -> Result<(), String> {
    let matches = cli::get_cli_arguments(std::env::args_os());

    let options = Options::from_cli_arguments(&matches)?;

    let command_strings: Vec<String> = matches
        .get_many::<String>("command")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let command_names: Vec<String> = matches
        .get_many::<String>("command-name")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let parameter_scan: Option<Vec<String>> = matches
        .get_many::<String>("parameter-scan")
        .map(|v| v.cloned().collect());
    let step_size = matches
        .get_one::<String>("parameter-step-size")
        .map(|s| s.as_str());
    let parameter_lists: Vec<(String, String)> = matches
        .get_occurrences::<String>("parameter-list")
        .map(|occurrences| {
            occurrences
                .map(|mut values| {
                    let name = values.next().cloned().unwrap_or_default();
                    let list = values.next().cloned().unwrap_or_default();
                    (name, list)
                })
                .collect()
        })
        .unwrap_or_default();

    let mut commands = build_commands(
        &command_strings,
        &command_names,
        parameter_scan
            .as_ref()
            .map(|v| (v[0].as_str(), v[1].as_str(), v[2].as_str())),
        step_size,
        &parameter_lists,
    )?;

    let has_reference = if let Some(reference) = matches.get_one::<String>("reference") {
        let name = matches
            .get_one::<String>("reference-name")
            .map(|s| s.as_str());
        commands.insert(0, Command::new(name, reference));
        true
    } else {
        false
    };

    let export_manager = ExportManager::from_cli_arguments(&matches)?;

    options.validate_against_command_list(&commands)?;

    let mut scheduler = Scheduler::new(&commands, &options, &export_manager, has_reference);
    scheduler.run_benchmarks()?;
    scheduler.print_relative_speed_comparison();
    scheduler.final_export()?;

    Ok(())
}

fn main() {
    match run() {
        Ok(()) => {}
        Err(e) => {
            eprintln!("{} {}", "Error:".red(), e);
            std::process::exit(1);
        }
    }
}
