//! CSV export.

use std::fmt::Write;

use super::Exporter;
use crate::benchmark::benchmark_result::BenchmarkResult;
use crate::options::SortOrder;
use crate::units::Unit;

#[derive(Default)]
pub struct CsvExporter {}

fn push_field(out: &mut String, field: &str) {
    let needs_quotes = field
        .bytes()
        .any(|c| c == b',' || c == b'"' || c == b'\n' || c == b'\r');
    if needs_quotes {
        out.push('"');
        for c in field.chars() {
            if c == '"' {
                out.push_str("\"\"");
            } else {
                out.push(c);
            }
        }
        out.push('"');
    } else {
        out.push_str(field);
    }
}

fn check_length(expected: usize, found: usize) -> Result<(), String> {
    if expected != found {
        Err(format!(
            "CSV error: found record with {} fields, but the previous record has {} fields",
            found, expected
        ))
    } else {
        Ok(())
    }
}

impl Exporter for CsvExporter {
    fn serialize(
        &self,
        results: &[BenchmarkResult],
        _unit: Option<Unit>,
        _sort_order: SortOrder,
    ) -> Result<Vec<u8>, String> {
        let mut out = String::with_capacity(64 + results.len() * 96);

        out.push_str("command,mean,stddev,median,user,system,min,max");
        let mut header_len = 8;
        if let Some(res) = results.first() {
            for param_name in res.parameters.keys() {
                out.push(',');
                push_field(&mut out, &format!("parameter_{}", param_name));
                header_len += 1;
            }
        }
        out.push('\n');

        for res in results {
            check_length(header_len, 8 + res.parameters.len())?;
            push_field(&mut out, &res.command);
            for v in [
                res.mean,
                res.stddev.unwrap_or(0.0),
                res.median,
                res.user,
                res.system,
                res.min,
                res.max,
            ] {
                let _ = write!(out, ",{}", v);
            }
            for v in res.parameters.values() {
                out.push(',');
                push_field(&mut out, v);
            }
            out.push('\n');
        }

        Ok(out.into_bytes())
    }
}
EOF
