//! * `standard_deviation`: the square root of the sample variance
//!
//! The sum of squared deviations can not be negative for well-behaved input.
//! If it is not a non-negative number (for example because the input contains
//! NaN or infinite values), the computation is aborted.

/// Computes the arithmetic mean of the given values.
///
/// The values are summed up from left to right and the sum is divided by the
/// number of values.
pub fn mean(v: &[f64]) -> f64 {
    let len = v.len() as f64;
    let sum = v.iter().fold(0.0, |acc, &x| acc + x);
    sum / len
}

/// Computes the median of the given values.
///
/// The values are sorted first. For an odd number of values, the middle value
/// is returned. Otherwise, the mean of the two middle values is returned.
pub fn median(v: &[f64]) -> f64 {
    assert!(!v.is_empty());
    let len = v.len();
    let mut sorted = v.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    if len % 2 == 0 {
        (sorted[len / 2 - 1] + sorted[len / 2]) / 2.0
    } else {
        sorted[len / 2]
    }
}

