pub fn harmonic_mean(v: &[f64]) -> f64 {
    let len = v.len() as f64;
    let sum = v.iter().fold(0.0, |acc, &x| acc + 1.0 / x);
    len / sum
}

/// Computes the geometric mean of the given (positive) values.
pub fn geometric_mean(v: &[f64]) -> f64 {
    let len = v.len() as f64;
    let sum_of_logs = v.iter().fold(0.0, |acc, &x| acc + x.ln());
    (sum_of_logs / len).exp()
}

/// Computes the median of the given values.
///
/// The values are sorted first. For an odd number of values, the middle value
/// is returned. Otherwise, the mean of the two middle values is returned.
pub fn median(v: &[f64]) -> f64 {
    assert!(!v.is_empty());
    let len = v.len();
    let mut sorted = v.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    if len % 2 == 0 {
        (sorted[len / 2 - 1] + sorted[len / 2]) / 2.0
    } else {
        sorted[len / 2]
    }
}

/// Computes the population variance of the given values (the sum of squared
/// deviations from the mean, divided by `n`).
pub fn population_variance(v: &[f64], mu: Option<f64>) -> f64 {
    let len = v.len() as f64;
    let mean = mu.unwrap_or_else(|| mean(v));
    let sum = v.iter().fold(0.0, |acc, &x| acc + (x - mean) * (x - mean));
    sum / len
